/// Placeholder for missing tree nodes in lc::buildTree({1, lc::null, 2}).
inline constexpr std::nullopt_t null = std::nullopt;

/// Thrown by harness helpers when an input/output cannot be handled.
struct HarnessError : std::runtime_error {
    using std::runtime_error::runtime_error;
};

/// Thrown by tests in a manual harness that have not been wired up yet.
struct NotWired : std::runtime_error {
    NotWired() : std::runtime_error("This test is not wired up yet: edit it in the TEST HARNESS section.") {}
};

inline std::string notWired() { throw NotWired(); }

// ---------------------------------------------------------------------------
// Serialization to LeetCode's output notation
// ---------------------------------------------------------------------------

inline std::string quote(const std::string& s) {
    std::string out = "\"";
    for (unsigned char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if (c < 0x20) {
                    char buf[8];
                    std::snprintf(buf, sizeof buf, "\\u%04x", c);
                    out += buf;
                } else {
                    out += static_cast<char>(c);
                }
        }
    }
    return out + "\"";
}

namespace detail {
template <class T, class = void>
struct is_tree_node : std::false_type {};
template <class T>
struct is_tree_node<T, std::void_t<decltype(std::declval<T&>().val), decltype(std::declval<T&>().left),
                                   decltype(std::declval<T&>().right)>> : std::true_type {};

template <class T, class = void>
struct is_list_node : std::false_type {};
template <class T>
struct is_list_node<T, std::void_t<decltype(std::declval<T&>().val), decltype(std::declval<T&>().next)>>
    : std::true_type {};

template <class>
inline constexpr bool always_false = false;

template <class T>
inline constexpr bool is_plain_integer =
    std::is_integral_v<T> && !std::is_same_v<T, bool> && !std::is_same_v<T, char>;
}  // namespace detail

// Declarations first so nested containers can use every overload.
template <class T, std::enable_if_t<detail::is_plain_integer<T>, int> = 0>
std::string serialize(T value);
inline std::string serialize(bool value);
inline std::string serialize(char value);
inline std::string serialize(double value);
inline std::string serialize(float value);
inline std::string serialize(const std::string& value);
inline std::string serialize(const char* value);
template <class T>
std::string serialize(const std::vector<T>& values);
template <class A, class B>
std::string serialize(const std::pair<A, B>& value);
template <class T>
std::string serialize(T* node);

template <class T, std::enable_if_t<detail::is_plain_integer<T>, int>>
std::string serialize(T value) {
    return std::to_string(value);
}
inline std::string serialize(bool value) { return value ? "true" : "false"; }
inline std::string serialize(char value) { return quote(std::string(1, value)); }
inline std::string serialize(double value) {
    if (std::isnan(value)) return "NaN";
    if (std::isinf(value)) return value > 0 ? "Infinity" : "-Infinity";
    char buf[64];
    std::snprintf(buf, sizeof buf, "%.5f", value);
    return buf;
}
inline std::string serialize(float value) { return serialize(static_cast<double>(value)); }
inline std::string serialize(const std::string& value) { return quote(value); }
inline std::string serialize(const char* value) { return value ? quote(value) : "null"; }

template <class T>
std::string serialize(const std::vector<T>& values) {
    std::string out = "[";
    bool first = true;
    for (const auto& item : values) {
        if (!first) out += ',';
        first = false;
        if constexpr (std::is_same_v<T, bool>) {
            out += serialize(static_cast<bool>(item));
        } else {
            out += serialize(item);
        }
    }
    return out + "]";
}

template <class A, class B>
std::string serialize(const std::pair<A, B>& value) {
    return "[" + serialize(value.first) + "," + serialize(value.second) + "]";
}

template <class Node>
std::string serializeList(const Node* head) {
    std::unordered_set<const Node*> seen;
    std::string out = "[";
    for (const Node* cur = head; cur != nullptr; cur = cur->next) {
        if (!seen.insert(cur).second) {
            throw HarnessError("The returned linked list contains a cycle.");
        }
        if (cur != head) out += ',';
        out += serialize(cur->val);
    }
    return out + "]";
}

template <class Node>
std::string serializeTree(const Node* root) {
    std::vector<std::string> items;
    std::unordered_set<const Node*> seen;
    std::queue<const Node*> pending;
    if (root) pending.push(root);
    while (!pending.empty()) {
        const Node* node = pending.front();
        pending.pop();
        if (!node) {
            items.emplace_back("null");
            continue;
        }
        if (!seen.insert(node).second) {
            throw HarnessError("The returned tree contains a cycle or a shared node.");
        }
        items.push_back(serialize(node->val));
        pending.push(node->left);
        pending.push(node->right);
    }
    while (!items.empty() && items.back() == "null") items.pop_back();
    std::string out = "[";
    for (std::size_t i = 0; i < items.size(); ++i) {
        if (i) out += ',';
        out += items[i];
    }
    return out + "]";
}

template <class T>
std::string serialize(T* node) {
    using Node = std::remove_cv_t<T>;
    if constexpr (detail::is_tree_node<Node>::value) {
        return serializeTree<Node>(node);
    } else if constexpr (detail::is_list_node<Node>::value) {
        return serializeList<Node>(node);
    } else {
        static_assert(detail::always_false<T>, "lc::serialize: unsupported pointer type");
        return {};
    }
}

/// In-place array problems judged on the first `k` elements (e.g. Remove Element):
/// renders `k, nums = [a,b,_,_]` exactly like LeetCode's examples.
template <class K, class T>
std::string serializePrefix(K k, const std::string& name, const std::vector<T>& values) {
    const long long count = static_cast<long long>(k);
    std::string out = serialize(k) + ", " + name + " = [";
    for (std::size_t i = 0; i < values.size(); ++i) {
        if (i) out += ',';
        out += static_cast<long long>(i) < count ? serialize(values[i]) : std::string("_");
    }
    return out + "]";
}

/// Collects the results of a design-problem operation sequence: `[null,1,null,-1]`.
class OutputList {
public:
    void null() { items_.emplace_back("null"); }
    template <class T>
    void add(const T& value) { items_.push_back(serialize(value)); }
    std::string str() const {
        std::string out = "[";
        for (std::size_t i = 0; i < items_.size(); ++i) {
            if (i) out += ',';
            out += items_[i];
        }
        return out + "]";
    }

private:
    std::vector<std::string> items_;
};

// ---------------------------------------------------------------------------
// Input builders
// ---------------------------------------------------------------------------

/// Builds a singly linked list: lc::buildList<ListNode>({1, 2, 3}).
template <class Node, class V = int>
Node* buildList(const std::vector<V>& values) {
    Node dummy(0);
    Node* tail = &dummy;
    for (const V& v : values) {
        tail->next = new Node(v);
        tail = tail->next;
    }
    return dummy.next;
}

/// Builds a binary tree from LeetCode's level-order notation:
/// lc::buildTree<TreeNode>({3, 9, 20, lc::null, lc::null, 15, 7}).
template <class Node, class V = int>
Node* buildTree(const std::vector<std::optional<V>>& values) {
    if (values.empty() || !values[0]) return nullptr;
    Node* root = new Node(*values[0]);
    std::queue<Node*> parents;
    parents.push(root);
    std::size_t i = 1;
    while (!parents.empty() && i < values.size()) {
        Node* parent = parents.front();
        parents.pop();
        if (i < values.size() && values[i]) {
            parent->left = new Node(*values[i]);
            parents.push(parent->left);
        }
        ++i;
        if (i < values.size() && values[i]) {
            parent->right = new Node(*values[i]);
            parents.push(parent->right);
        }
        ++i;
    }
    return root;
}

/// Frees a list built by buildList (safe on cycles). Not called automatically,
/// because solutions often return nodes that belong to their inputs.
template <class Node>
void deleteList(Node* head) {
    std::unordered_set<Node*> seen;
    while (head && seen.insert(head).second) {
        Node* next = head->next;
        delete head;
        head = next;
    }
}

/// Frees a tree built by buildTree.
template <class Node>
void deleteTree(Node* root) {
    if (!root) return;
    deleteTree(root->left);
    deleteTree(root->right);
    delete root;
}

/// Returns the first node with the given value (pre-order), or nullptr.
template <class Node, class V>
Node* findNode(Node* root, const V& value) {
    if (!root) return nullptr;
    if (root->val == value) return root;
    if (Node* left = findNode(root->left, value)) return left;
    return findNode(root->right, value);
}

/// Returns the node at `index` (0-based) of a list, or nullptr when index < 0.
template <class Node>
Node* nodeAt(Node* head, int index) {
    if (index < 0) return nullptr;
    while (head && index-- > 0) head = head->next;
    return head;
}

/// Links the tail of a list to the node at `pos` (LeetCode's cycle notation); pos = -1 means no cycle.
template <class Node>
Node* makeCycle(Node* head, int pos) {
    if (!head || pos < 0) return head;
    Node* tail = head;
    while (tail->next) tail = tail->next;
    tail->next = nodeAt(head, pos);
    return head;
}

