/// Measures the time spent in the solution call; the harness falls back to the whole test body.
class Timer {
public:
    void start() {
        started_ = true;
        running_ = true;
        begin_ = std::chrono::steady_clock::now();
    }
    void stop() {
        if (running_) {
            elapsed_ += std::chrono::steady_clock::now() - begin_;
            running_ = false;
        }
    }
    bool started() const { return started_; }
    double micros() const { return std::chrono::duration<double, std::micro>(elapsed_).count(); }

private:
    bool started_ = false;
    bool running_ = false;
    std::chrono::steady_clock::time_point begin_{};
    std::chrono::steady_clock::duration elapsed_{};
};

/// Runs the test cases defined in main().
///  - no arguments:          runs every test and prints a readable report (use this when debugging)
///  - --lc-test N:           runs only test N
///  - --lc-list:             lists the test ids (used by the extension)
///  - --lc-nonce X:          emits machine-readable result lines for the extension
class Harness {
public:
    Harness(int argc, char** argv) {
        for (int i = 1; i < argc; ++i) {
            const std::string arg = argv[i];
            if (arg == "--lc-test" && i + 1 < argc) {
                selected_ = std::atoi(argv[++i]);
            } else if (arg == "--lc-nonce" && i + 1 < argc) {
                nonce_ = argv[++i];
            } else if (arg == "--lc-list") {
                listOnly_ = true;
            }
        }
    }

    template <class Body>
    void test(int id, const char* expected, Body&& body) {
        if (listOnly_) {
            emit("{\"event\":\"test\",\"id\":" + std::to_string(id) + "}");
            return;
        }
        if (selected_ != 0 && selected_ != id) return;
        ++ran_;
        if (!machine()) std::cout << "---- Test Case " << id << " ----" << std::endl;

        Timer timer;
        std::string output;
        std::string status = "ok";
        std::string error;
        const auto begin = std::chrono::steady_clock::now();
        try {
            output = body(timer);
        } catch (const NotWired& e) {
            status = "not_wired";
            error = e.what();
        } catch (const std::exception& e) {
            status = "exception";
            error = e.what();
        } catch (...) {
            status = "exception";
            error = "unknown exception";
        }
        timer.stop();
        const double micros = timer.started()
            ? timer.micros()
            : std::chrono::duration<double, std::micro>(std::chrono::steady_clock::now() - begin).count();

        if (machine()) {
            std::string line = "{\"event\":\"result\",\"id\":" + std::to_string(id) + ",\"status\":" + quote(status) +
                               ",\"output\":" + quote(output) + ",\"timeUs\":" + std::to_string(micros);
            if (expected) line += ",\"expected\":" + quote(expected);
            if (!error.empty()) line += ",\"error\":" + quote(error);
            emit(line + "}");
            return;
        }
        if (status != "ok") {
            std::cout << "  Error:    " << error << "\n";
        } else {
            std::cout << "  Output:   " << output << "\n";
            if (expected) {
                const bool same = output == expected;
                matched_ += same ? 1 : 0;
                std::cout << "  Expected: " << expected << "\n  " << (same ? "[match]" : "[differs]") << "\n";
            }
        }
        std::cout << "  Time:     " << std::fixed << std::setprecision(3) << micros / 1000.0 << " ms\n" << std::endl;
    }

    int finish() {
        if (!machine() && !listOnly_) {
            std::cout << matched_ << " / " << ran_
                      << " outputs match the expected text exactly.\n"
                         "(Run \"LeetCode: Run Tests\" in VS Code for problem-aware comparison.)"
                      << std::endl;
        }
        return 0;
    }

private:
    bool machine() const { return !nonce_.empty(); }
    void emit(const std::string& json) const {
        std::cout << std::flush;
        std::printf("\n@@LCR:%s:%s\n", nonce_.c_str(), json.c_str());
        std::fflush(stdout);
    }

    int selected_ = 0;
    bool listOnly_ = false;
    std::string nonce_;
    int ran_ = 0;
    int matched_ = 0;
};

